package rocketbrain.signature;

import com.sun.source.tree.*;
import com.sun.source.util.*;
import java.util.*;
import javax.lang.model.element.*;
import javax.lang.model.type.*;
import javax.lang.model.util.Elements;

import static rocketbrain.signature.SignatureInspector.object;

/** Proves the supported initializer and loop shapes against actual javac bindings. */
final class ConversionInspector {
    private final Trees trees;
    private final Elements elements;
    private final SourcePositions positions;
    private final CompilationUnitTree unit;
    private final String text;
    private final Map<Element, List<TreePath>> references = new HashMap<>();

    ConversionInspector(JavacTask task, CompilationUnitTree unit, String text) {
        this.trees = Trees.instance(task);
        this.elements = task.getElements();
        this.positions = trees.getSourcePositions();
        this.unit = unit;
        this.text = text;
    }

    private TreePath path(TreePath parent, Tree child) { return new TreePath(parent, child); }
    private int start(Tree tree) { return (int) positions.getStartPosition(unit, tree); }
    private int end(Tree tree) { return (int) positions.getEndPosition(unit, tree); }
    private Element element(TreePath parent, Tree child) { return trees.getElement(path(parent, child)); }

    List<Map<String, Object>> inspect() {
        new TreePathScanner<Void, Void>() {
            @Override public Void visitIdentifier(IdentifierTree node, Void unused) {
                Element target = trees.getElement(getCurrentPath());
                if (target != null) references.computeIfAbsent(target, key -> new ArrayList<>()).add(getCurrentPath());
                return super.visitIdentifier(node, unused);
            }
        }.scan(unit, null);

        var result = new ArrayList<Map<String, Object>>();
        new TreePathScanner<Void, Void>() {
            void add(Map<String, Object> site) {
                if (site != null) result.add(site);
                if (result.size() > 400) throw new IllegalArgumentException("Too many supported Java conversion sites in this file.");
            }
            @Override public Void visitVariable(VariableTree node, Void unused) {
                add(function(getCurrentPath(), node));
                return super.visitVariable(node, unused);
            }
            @Override public Void visitForLoop(ForLoopTree node, Void unused) {
                add(indexedLoop(getCurrentPath(), node));
                return super.visitForLoop(node, unused);
            }
            @Override public Void visitEnhancedForLoop(EnhancedForLoopTree node, Void unused) {
                add(enhancedLoop(getCurrentPath(), node));
                return super.visitEnhancedForLoop(node, unused);
            }
        }.scan(unit, null);
        return result;
    }

    private static boolean local(Element element) {
        return element instanceof VariableElement && Set.of(ElementKind.LOCAL_VARIABLE, ElementKind.PARAMETER).contains(element.getKind());
    }

    private ExecutableElement sam(VariableElement variable) {
        if (!(variable.asType() instanceof DeclaredType declared) || !(declared.asElement() instanceof TypeElement type) ||
                !elements.isFunctionalInterface(type) || type.getKind() != ElementKind.INTERFACE) return null;
        String name = type.getQualifiedName().toString();
        boolean platform = name.startsWith("java.util.function.") || Set.of("java.lang.Runnable","java.util.concurrent.Callable").contains(name);
        if (!platform && (name.isEmpty() || !sourceContract(type,new HashSet<>()))) return null;
        var methods = elements.getAllMembers(type).stream()
            .filter(member -> member instanceof ExecutableElement && member.getModifiers().contains(Modifier.ABSTRACT)).toList();
        if (methods.size() != 1) return null;
        ExecutableElement method = (ExecutableElement)methods.getFirst();
        return method.getTypeParameters().isEmpty() ? method : null;
    }

    private boolean sourceContract(TypeElement type, Set<TypeElement> checked) {
        if (!checked.add(type)) return true;
        if (checked.size() > 100 || trees.getPath(type) == null || type.getModifiers().contains(Modifier.SEALED)) return false;
        for (Element member : type.getEnclosedElements()) {
            if (member instanceof VariableElement field && field.getConstantValue() == null) return false;
        }
        for (TypeMirror parent : type.getInterfaces()) {
            if (!(parent instanceof DeclaredType declared) || !(declared.asElement() instanceof TypeElement inherited) ||
                !sourceContract(inherited,checked)) return false;
        }
        return true;
    }

    private static Tree executionBoundary(TreePath path) {
        for (; path != null; path = path.getParentPath()) {
            Tree node = path.getLeaf();
            if (node instanceof MethodTree || node instanceof LambdaExpressionTree || node instanceof ClassTree) return node;
        }
        return null;
    }

    private boolean directCalls(TreePath site, VariableElement variable, ExecutableElement method) {
        Tree boundary = executionBoundary(site);
        for (var use : references.getOrDefault(variable, List.of())) {
            TreePath selection = use.getParentPath(), invocation = selection.getParentPath();
            if (executionBoundary(use) != boundary ||
                    !(selection.getLeaf() instanceof MemberSelectTree select) || select.getExpression() != use.getLeaf() ||
                    !(invocation.getLeaf() instanceof MethodInvocationTree call) || call.getMethodSelect() != select ||
                    !method.equals(trees.getElement(selection))) return false;
        }
        return true;
    }

    private Map<String, Object> function(TreePath site, VariableTree declaration) {
        if (!(trees.getElement(site) instanceof VariableElement variable) || variable.getKind() != ElementKind.LOCAL_VARIABLE ||
                declaration.getType() == null || start(declaration.getType()) < 0 || end(declaration.getType()) <= start(declaration.getType())) return null;
        Tree initializer = declaration.getInitializer();
        if (!(initializer instanceof LambdaExpressionTree || initializer instanceof NewClassTree) ||
                start(initializer) < 0 || end(initializer) <= start(initializer)) return null;
        ExecutableElement method = sam(variable);
        if (method == null || !directCalls(site, variable, method)) return null;

        TreePath initPath = path(site, initializer), bodyPath;
        List<? extends VariableTree> parameters;
        String kind;
        int actionOffset;
        if (initializer instanceof LambdaExpressionTree lambda) {
            kind = "lambda";
            parameters = lambda.getParameters();
            bodyPath = path(initPath, lambda.getBody());
            actionOffset = text.lastIndexOf("->", start(lambda.getBody())) + 1;
            if (actionOffset <= start(initializer)) return null;
        } else {
            kind = "anonymous";
            var created = (NewClassTree) initializer;
            if (created.getClassBody() == null || created.getEnclosingExpression() != null || !created.getArguments().isEmpty()) return null;
            TreePath bodyClass = path(initPath, created.getClassBody());
            if (!trees.getTypeMirror(path(initPath, created.getIdentifier())).toString().equals(variable.asType().toString())) return null;
            var members = created.getClassBody().getMembers().stream().filter(member -> end(member) > start(member)).toList();
            if (members.size() != 1 || !(members.getFirst() instanceof MethodTree implementation) ||
                    !implementation.getName().contentEquals(method.getSimpleName()) || implementation.getBody() == null ||
                    !(trees.getElement(path(bodyClass, implementation)) instanceof ExecutableElement executor) ||
                    !executor.getModifiers().equals(Set.of(Modifier.PUBLIC)) ||
                    executor.getAnnotationMirrors().stream().anyMatch(annotation -> !annotation.getAnnotationType().toString().equals("java.lang.Override"))) return null;
            parameters = implementation.getParameters();
            bodyPath = path(path(bodyClass, implementation), implementation.getBody());
            actionOffset = start(initializer) + 4;
        }
        TreePath paramsParent = kind.equals("lambda") ? initPath : bodyPath.getParentPath();
        var parameterBindings = new LinkedHashMap<Element, String>();
        for (var parameter : parameters) {
            Element binding = element(paramsParent, parameter);
            if (!(binding instanceof VariableElement param) || !param.getAnnotationMirrors().isEmpty() ||
                    !param.asType().getAnnotationMirrors().isEmpty()) return null;
            parameterBindings.put(param, param.getSimpleName() + ":" + param.asType());
        }
        TreePath normalized = normalizeBody(bodyPath, method.getReturnType().getKind() == TypeKind.VOID);
        if (normalized == null) return null;
        var proof = bodyBindings(normalized, parameterBindings);
        if (proof == null) return null;
        return object("kind", kind, "start", start(initializer), "end", end(initializer), "cursorStart", start(declaration),
            "actionOffset", actionOffset, "sam", SignatureInspector.key(method), "type", variable.asType().toString(),
            "parameters", parameterBindings.values(), "body", normalized.getLeaf().toString(),
            "bindings", proof.bindings(), "captures", proof.captures(), "callTargets", proof.callTargets());
    }

    private TreePath normalizeBody(TreePath body, boolean isVoid) {
        if (!(body.getLeaf() instanceof BlockTree block)) return body;
        if (block.getStatements().isEmpty() && isVoid) return body;
        if (block.getStatements().size() != 1) return null;
        StatementTree statement = block.getStatements().getFirst();
        Tree expression = statement instanceof ReturnTree value && !isVoid ? value.getExpression() :
            statement instanceof ExpressionStatementTree value && isVoid ? value.getExpression() : null;
        return expression == null ? null : path(path(body, statement), expression);
    }

    private record BodyProof(List<String> bindings, Collection<String> captures, Collection<String> callTargets) {}

    private BodyProof bodyBindings(TreePath body, Map<Element, String> parameters) {
        var bindings = new ArrayList<String>();
        var captures = new LinkedHashSet<String>();
        var callTargets = new LinkedHashSet<String>();
        var unsafe = new boolean[1];
        new TreePathScanner<Void, Void>() {
            void keep(Tree node, String name, boolean qualified) {
                Element target = trees.getElement(getCurrentPath());
                TypeMirror type = trees.getTypeMirror(getCurrentPath());
                if (name.equals("this") || name.equals("super") || target == null || type == null ||
                        !qualified && (target.getKind().isField() || target instanceof ExecutableElement) &&
                        !target.getModifiers().contains(Modifier.STATIC)) {
                    unsafe[0] = true;
                    return;
                }
                String key;
                if (parameters.containsKey(target)) key = "parameter:" + parameters.get(target);
                else if (target instanceof ExecutableElement method) {
                    key = SignatureInspector.key(method);
                    callTargets.add(key);
                }
                else if (target instanceof VariableElement captured && Set.of(ElementKind.LOCAL_VARIABLE,ElementKind.PARAMETER,
                        ElementKind.EXCEPTION_PARAMETER,ElementKind.RESOURCE_VARIABLE,ElementKind.BINDING_VARIABLE).contains(target.getKind())) {
                    TreePath declaration = trees.getPath(captured);
                    if (declaration == null || declaration.getCompilationUnit() != unit || start(declaration.getLeaf()) < 0 ||
                        start(declaration.getLeaf()) >= start(body.getLeaf())) {
                        unsafe[0] = true;
                        return;
                    }
                    captures.add(captured.getSimpleName().toString());
                    key = "capture:" + start(declaration.getLeaf()) + ":" + captured.getSimpleName() + ":" + captured.asType();
                }
                else key = target.getKind() + ":" + target.getEnclosingElement() + ":" + target;
                bindings.add(node.getKind() + ":" + key + ":" + type);
            }
            @Override public Void visitIdentifier(IdentifierTree node, Void unused) {
                keep(node, node.getName().toString(), false);
                return super.visitIdentifier(node, unused);
            }
            @Override public Void visitMemberSelect(MemberSelectTree node, Void unused) {
                keep(node, node.getIdentifier().toString(), true);
                return super.visitMemberSelect(node, unused);
            }
            @Override public Void visitLambdaExpression(LambdaExpressionTree node, Void unused) { unsafe[0] = true; return null; }
            @Override public Void visitNewClass(NewClassTree node, Void unused) { unsafe[0] = true; return null; }
            @Override public Void visitMemberReference(MemberReferenceTree node, Void unused) { unsafe[0] = true; return null; }
        }.scan(body, null);
        return unsafe[0] ? null : new BodyProof(bindings,captures,callTargets);
    }

    private record Accumulation(Element accumulator, TreePath value) {}

    private Accumulation accumulation(TreePath loop, StatementTree statement) {
        TreePath body = path(loop, statement);
        if (statement instanceof BlockTree block) {
            if (block.getStatements().size() != 1) return null;
            body = path(body, block.getStatements().getFirst());
        }
        if (!(body.getLeaf() instanceof ExpressionStatementTree expression) ||
                !(expression.getExpression() instanceof CompoundAssignmentTree assignment) ||
                assignment.getKind() != Tree.Kind.PLUS_ASSIGNMENT || !(assignment.getVariable() instanceof IdentifierTree)) return null;
        TreePath operation = path(body, assignment);
        Element accumulator = element(operation, assignment.getVariable());
        if (!local(accumulator) || !accumulator.asType().getKind().isPrimitive() ||
                accumulator.asType().getKind() == TypeKind.BOOLEAN) return null;
        return new Accumulation(accumulator, path(operation, assignment.getExpression()));
    }

    private Element primitiveArray(TreePath parent, Tree tree) {
        if (!(tree instanceof IdentifierTree)) return null;
        Element array = element(parent, tree);
        return local(array) && array.asType() instanceof ArrayType type &&
            type.getComponentType().getKind().isPrimitive() && type.getComponentType().getKind() != TypeKind.BOOLEAN ? array : null;
    }

    private Map<String, Object> indexedLoop(TreePath site, ForLoopTree loop) {
        if (loop.getInitializer().size() != 1 || !(loop.getInitializer().getFirst() instanceof VariableTree variable) ||
                !(variable.getInitializer() instanceof LiteralTree literal) || !Integer.valueOf(0).equals(literal.getValue()) ||
                !(loop.getCondition() instanceof BinaryTree less) || less.getKind() != Tree.Kind.LESS_THAN ||
                !(less.getLeftOperand() instanceof IdentifierTree) || !(less.getRightOperand() instanceof MemberSelectTree length) ||
                !length.getIdentifier().contentEquals("length") || loop.getUpdate().size() != 1 ||
                !(loop.getUpdate().getFirst().getExpression() instanceof UnaryTree increment) ||
                !Set.of(Tree.Kind.POSTFIX_INCREMENT, Tree.Kind.PREFIX_INCREMENT).contains(increment.getKind())) return null;
        Element index = element(site, variable);
        if (!local(index) || index.asType().getKind() != TypeKind.INT ||
                !index.equals(element(path(site, less), less.getLeftOperand())) ||
                !index.equals(element(path(path(site, loop.getUpdate().getFirst()), increment), increment.getExpression()))) return null;
        Element array = primitiveArray(path(path(site, less), length), length.getExpression());
        Accumulation accumulation = accumulation(site, loop.getStatement());
        if (array == null || accumulation == null || index.equals(accumulation.accumulator()) ||
                !(accumulation.value().getLeaf() instanceof ArrayAccessTree access) ||
                !array.equals(primitiveArray(accumulation.value(), access.getExpression())) ||
                !index.equals(element(accumulation.value(), access.getIndex()))) return null;
        return loopSite("indexed", loop, array, accumulation.accumulator());
    }

    private Map<String, Object> enhancedLoop(TreePath site, EnhancedForLoopTree loop) {
        Element array = primitiveArray(site, loop.getExpression());
        Element variable = element(site, loop.getVariable());
        Accumulation accumulation = accumulation(site, loop.getStatement());
        if (array == null || !local(variable) ||
                !((ArrayType) array.asType()).getComponentType().toString().equals(variable.asType().toString()) ||
                accumulation == null || variable.equals(accumulation.accumulator()) ||
                !(accumulation.value().getLeaf() instanceof IdentifierTree) ||
                !variable.equals(trees.getElement(accumulation.value()))) return null;
        return loopSite("enhanced", loop, array, accumulation.accumulator());
    }

    private Map<String, Object> loopSite(String kind, Tree loop, Element array, Element accumulator) {
        return object("kind", kind, "start", start(loop), "end", end(loop), "cursorStart", start(loop),
            "actionOffset", start(loop) + 1, "array", array.getSimpleName().toString(), "arrayType", array.asType().toString(),
            "accumulator", accumulator.getSimpleName().toString(), "accumulatorType", accumulator.asType().toString());
    }
}

ExtractMethodInspector.java:
package rocketbrain.signature;

import com.sun.source.tree.*;
import com.sun.source.util.*;
import java.util.*;
import javax.lang.model.element.*;
import javax.lang.model.type.*;
import javax.lang.model.util.Elements;
import static rocketbrain.signature.SignatureInspector.object;

/** Proves a statement sequence and the exact call replacing it using attributed source. */
final class ExtractMethodInspector {
    private final Trees trees;
    private final Elements elements;
    private final SourcePositions positions;
    private final CompilationUnitTree unit;
    private final String text;

    ExtractMethodInspector(JavacTask task, CompilationUnitTree unit, String text) {
        trees = Trees.instance(task);
        elements = task.getElements();
        positions = trees.getSourcePositions();
        this.unit = unit;
        this.text = text;
    }

    private int start(Tree tree) { return (int)positions.getStartPosition(unit,tree); }
    private int end(Tree tree) { return (int)positions.getEndPosition(unit,tree); }
    private String source(Tree tree) { return text.substring(start(tree),end(tree)); }
    private Map<String,Object> error(String reason) { return object("error",reason); }

    Map<String,Object> inspect(int from, int to, String name, int callOffset) {
        List<TreePath> paths = new ArrayList<>();
        new TreePathScanner<Void,Void>() {
            @Override public Void visitMethod(MethodTree method, Void unused) {
                if (method.getBody()!=null && start(method.getBody())<from && to<end(method.getBody())) paths.add(getCurrentPath());
                return super.visitMethod(method,unused);
            }
        }.scan(unit,null);
        if (paths.size()!=1) return error("Select complete statements in one ordinary named Java method.");
        TreePath path = paths.getFirst();
        MethodTree method = (MethodTree)path.getLeaf();
        if (!(trees.getElement(path) instanceof ExecutableElement declaration) || declaration.getKind()!=ElementKind.METHOD ||
            !(declaration.getEnclosingElement() instanceof TypeElement owner) || owner.getKind()!=ElementKind.CLASS ||
            !Set.of(NestingKind.TOP_LEVEL,NestingKind.MEMBER).contains(owner.getNestingKind())) {
            return error("Select a method in an ordinary named Java class.");
        }
        Selection selection = selection(path,method,from,to);
        if (selection==null) return error("Select complete trailing statements or a contiguous sequence in one Java block.");
        var selected = selection.statements();
        boolean returnsValue = selection.endsMethod() && selected.getLast() instanceof ReturnTree returned &&
            returned.getExpression()!=null;
        if (returnsValue && selected.size()<2) return error("Select at least two complete trailing statements ending with a return value.");
        if (callOffset<0 && nameUsed(owner,name)) return error("Choose a new method name unused in the current Java source and its hierarchy.");
        boolean voidMethod = declaration.getReturnType().getKind()==TypeKind.VOID;
        boolean outputHelper = callOffset>=0 && !returnsValue && !voidMethod;
        var methodStatements = method.getBody().getStatements();
        if (callOffset>=0 && (!declaration.getSimpleName().contentEquals(name) ||
            !declaration.getModifiers().contains(Modifier.PRIVATE) || selection.block().getLeaf()!=method.getBody() ||
            selected.getFirst()!=methodStatements.getFirst() || selected.size()+(outputHelper?1:0)!=methodStatements.size() ||
            returnsValue && voidMethod)) {
            return error("Javac could not verify the generated private helper.");
        }
        BodyProof body = new BodyProof(declaration,from,to,returnsValue);
        for (StatementTree statement : selected) {
            if (body.supports(statement)) body.scan(new TreePath(selection.block(),statement),null);
            else body.invalid=true;
        }
        if (body.invalid) return error("Use local statements, if, loops or a trailing return. Captured writes, nonlocal control flow, local types and nested lambdas are unsupported.");
        List<VariableElement> outputs = callOffset<0?usedOutside(path,body.locals.keySet(),from,to):
            outputHelper?returnedLocals(path,declaration,methodStatements.getLast(),body.locals.keySet()):List.of();
        if (outputs==null || outputs.size()>4 || outputs.stream().anyMatch(value->!transferable(value,selection))) {
            return error("A local value used outside the extraction must be an initialized, nonconstant local declared directly in the selection. Use at most four output values.");
        }
        if (callOffset<0 && !outputs.isEmpty()) {
            String resultType=name.substring(0,1).toUpperCase(Locale.ROOT)+name.substring(1)+"Values";
            if (nameUsed(owner,name+"Result") || nameUsed(owner,resultType)) {
                return error("Choose a helper name whose generated result variable and type are unused.");
            }
        }
        Map<String,Object> result = object("owner",owner.getQualifiedName().toString(),"className",owner.getSimpleName().toString(),
            "method",SignatureInspector.key(declaration),"staticMethod",declaration.getModifiers().contains(Modifier.STATIC),
            "methodEnd",end(method),"methodStart",start(method),"start",from,"end",to,"statementCount",selected.size(),
            "returnsValue",returnsValue,"sourceReturn",returnsValue?source(method.getReturnType()):"void",
            "returnType",returnsValue?declaration.getReturnType().toString():"void",
            "sourceTypeParameters",method.getTypeParameters().stream().map(this::source).toList(),
            "typeNames",declaration.getTypeParameters().stream().map(parameter->parameter.getSimpleName().toString()).toList(),
            "sourceThrows",method.getThrows().stream().map(this::source).toList(),
            "throwsTypes",declaration.getThrownTypes().stream().map(Object::toString).toList(),
            "captures",body.captures.keySet().stream().map(this::variable).toList(),"outputs",outputs.stream().map(this::output).toList(),
            "bindings",body.bindings,"selected",selected.stream().map(Object::toString).toList());
        if (callOffset>=0) {
            result.put("parameters",declaration.getParameters().stream().map(this::variable).toList());
            result.put("call",call(callOffset,declaration,returnsValue,outputs));
            if (outputHelper) result.put("outputType",declaration.getReturnType().toString());
        }
        return result;
    }

    private record Selection(TreePath block,List<? extends StatementTree> statements,boolean endsMethod) {}

    private Selection selection(TreePath methodPath,MethodTree method,int from,int to) {
        List<Selection> matches = new ArrayList<>();
        new TreePathScanner<Void,Void>() {
            @Override public Void visitBlock(BlockTree block,Void unused) {
                if (start(block)>=from || end(block)<=to) return null;
                var statements=block.getStatements();
                int first=0;
                while (first<statements.size() && start(statements.get(first))<from) first++;
                int last=first;
                while (last<statements.size() && end(statements.get(last))<=to) last++;
                if (first<last && start(statements.get(first))==from && end(statements.get(last-1))==to) {
                    matches.add(new Selection(getCurrentPath(),statements.subList(first,last),
                        block==method.getBody() && last==statements.size()));
                }
                return super.visitBlock(block,unused);
            }
        }.scan(new TreePath(methodPath,method.getBody()),null);
        return matches.size()==1?matches.getFirst():null;
    }

    private List<VariableElement> usedOutside(TreePath method,Set<VariableElement> locals,int from,int to) {
        if (locals.isEmpty()) return List.of();
        Set<VariableElement> observed = new HashSet<>();
        new TreePathScanner<Void,Void>() {
            @Override public Void visitIdentifier(IdentifierTree tree,Void unused) {
                int offset=start(tree);
                if ((offset<from || offset>=to) && trees.getElement(getCurrentPath()) instanceof VariableElement value &&
                    locals.contains(value)) observed.add(value);
                return super.visitIdentifier(tree,unused);
            }
        }.scan(method,null);
        return locals.stream().filter(observed::contains).toList();
    }

    private boolean transferable(VariableElement value,Selection selection) {
        TreePath declaration=trees.getPath(value);
        return declaration!=null && declaration.getParentPath().getLeaf()==selection.block().getLeaf() &&
            declaration.getLeaf() instanceof VariableTree variable && variable.getInitializer()!=null &&
            variable.getModifiers().getAnnotations().isEmpty() && value.getConstantValue()==null;
    }

    private Map<String,Object> output(VariableElement value) {
        return object("name",value.getSimpleName().toString(),"type",value.asType().toString(),
            "final",value.getModifiers().contains(Modifier.FINAL));
    }

    private List<VariableElement> returnedLocals(TreePath method,ExecutableElement helper,StatementTree statement,
        Set<VariableElement> locals) {
        if (!(helper.getReturnType() instanceof DeclaredType returnType) || !(returnType.asElement() instanceof TypeElement record) ||
            record.getKind()!=ElementKind.RECORD || !(statement instanceof ReturnTree returned) ||
            !(returned.getExpression() instanceof NewClassTree created) || created.getClassBody()!=null) return null;
        TreePath at=new TreePath(new TreePath(new TreePath(method,((MethodTree)method.getLeaf()).getBody()),returned),created);
        if (!helper.getReturnType().toString().equals(trees.getTypeMirror(at).toString())) return null;
        List<VariableElement> outputs = new ArrayList<>();
        for (ExpressionTree argument : created.getArguments()) {
            if (!(argument instanceof IdentifierTree) ||
                !(trees.getElement(new TreePath(at,argument)) instanceof VariableElement value) ||
                !locals.contains(value) || outputs.contains(value)) return null;
            outputs.add(value);
        }
        return outputs.isEmpty()?null:outputs;
    }

    private Map<String,Object> variable(VariableElement element) {
        TreePath path = trees.getPath(element);
        return object("name",element.getSimpleName().toString(),"type",element.asType().toString(),
            "start",path==null||path.getCompilationUnit()!=unit?-1:start(path.getLeaf()));
    }

    private boolean nameUsed(TypeElement owner, String name) {
        if (elements.getAllMembers(owner).stream().anyMatch(member->member instanceof ExecutableElement method &&
            method.getSimpleName().contentEquals(name))) return true;
        boolean[] used = {false};
        new TreeScanner<Void,Void>() {
            @Override public Void visitIdentifier(IdentifierTree tree,Void unused) {
                used[0]|=tree.getName().contentEquals(name);return super.visitIdentifier(tree,unused);
            }
            @Override public Void visitMemberSelect(MemberSelectTree tree,Void unused) {
                used[0]|=tree.getIdentifier().contentEquals(name);return super.visitMemberSelect(tree,unused);
            }
            @Override public Void visitMemberReference(MemberReferenceTree tree,Void unused) {
                used[0]|=tree.getName().contentEquals(name);return super.visitMemberReference(tree,unused);
            }
        }.scan(unit,null);
        return used[0];
    }

    private Map<String,Object> call(int offset,ExecutableElement helper,boolean returnsValue,List<VariableElement> outputs) {
        List<Map<String,Object>> calls = new ArrayList<>();
        new TreePathScanner<Void,Void>() {
            @Override public Void visitMethodInvocation(MethodInvocationTree call, Void unused) {
                TreePath path = getCurrentPath(), parent = path.getParentPath();
                if (start(call)!=offset || !helper.equals(trees.getElement(path))) return super.visitMethodInvocation(call,unused);
                boolean rightStatement=returnsValue?parent.getLeaf() instanceof ReturnTree:
                    outputs.isEmpty()?parent.getLeaf() instanceof ExpressionStatementTree:restoresOutputs(parent,call,helper,outputs);
                if (rightStatement) {
                    List<Map<String,Object>> arguments = new ArrayList<>();
                    for (ExpressionTree expression : call.getArguments()) {
                        if (!(expression instanceof IdentifierTree) ||
                            !(trees.getElement(new TreePath(path,expression)) instanceof VariableElement variable)) return null;
                        arguments.add(variable(variable));
                    }
                    TreePath caller = parent;
                    while (caller!=null && !(caller.getLeaf() instanceof MethodTree)) caller=caller.getParentPath();
                    if (caller!=null && trees.getElement(caller) instanceof ExecutableElement method) {
                        calls.add(object("caller",SignatureInspector.key(method),"arguments",arguments,
                            "type",trees.getTypeMirror(path).toString()));
                    }
                }
                return super.visitMethodInvocation(call,unused);
            }
        }.scan(unit,null);
        return calls.size()==1?calls.getFirst():null;
    }

    private boolean restoresOutputs(TreePath declaration,MethodInvocationTree call,ExecutableElement helper,List<VariableElement> outputs) {
        if (!(declaration.getLeaf() instanceof VariableTree temporary) || temporary.getInitializer()!=call ||
            !(declaration.getParentPath().getLeaf() instanceof BlockTree block) ||
            !(trees.getElement(declaration) instanceof VariableElement result) ||
            !result.asType().toString().equals(helper.getReturnType().toString()) ||
            !(helper.getReturnType() instanceof DeclaredType type)) return false;
        var statements=block.getStatements();
        int first=statements.indexOf(temporary)+1;
        if (first<1 || first+outputs.size()>statements.size()) return false;
        for (int index=0;index<outputs.size();index++) {
            if (!(statements.get(first+index) instanceof VariableTree restored) ||
                !(restored.getInitializer() instanceof MethodInvocationTree accessor) ||
                !accessor.getArguments().isEmpty() || !(accessor.getMethodSelect() instanceof MemberSelectTree select)) return false;
            TreePath variablePath=new TreePath(declaration.getParentPath(),restored);
            TreePath accessorPath=new TreePath(variablePath,accessor);
            TreePath receiver=new TreePath(new TreePath(accessorPath,select),select.getExpression());
            if (!(trees.getElement(variablePath) instanceof VariableElement variable) ||
                !output(outputs.get(index)).equals(output(variable)) || !result.equals(trees.getElement(receiver)) ||
                !(trees.getElement(accessorPath) instanceof ExecutableElement getter) ||
                !getter.getEnclosingElement().equals(type.asElement()) ||
                !getter.getSimpleName().contentEquals("value"+index)) return false;
        }
        return true;
    }

    private final class BodyProof extends TreePathScanner<Void,Void> {
        private static final Set<Tree.Kind> LOOPS = Set.of(Tree.Kind.FOR_LOOP,Tree.Kind.ENHANCED_FOR_LOOP,
            Tree.Kind.WHILE_LOOP,Tree.Kind.DO_WHILE_LOOP);
        private static final Set<Tree.Kind> STATEMENTS = Set.of(Tree.Kind.BLOCK,Tree.Kind.VARIABLE,Tree.Kind.IF,
            Tree.Kind.RETURN,Tree.Kind.THROW,Tree.Kind.EXPRESSION_STATEMENT,Tree.Kind.FOR_LOOP,
            Tree.Kind.ENHANCED_FOR_LOOP,Tree.Kind.WHILE_LOOP,Tree.Kind.DO_WHILE_LOOP,Tree.Kind.BREAK,Tree.Kind.CONTINUE);
        final ExecutableElement method;
        final int from, to;
        final boolean returnsValue;
        final List<String> bindings = new ArrayList<>();
        final Map<VariableElement,Integer> locals = new LinkedHashMap<>(), captures = new LinkedHashMap<>();
        boolean invalid;

        BodyProof(ExecutableElement method,int from,int to,boolean returnsValue) {
            this.method=method;this.from=from;this.to=to;this.returnsValue=returnsValue;
        }

        private boolean supports(Tree tree) {
            boolean unsupportedStatement = tree instanceof StatementTree && !STATEMENTS.contains(tree.getKind());
            return !(unsupportedStatement || tree instanceof ReturnTree && !returnsValue ||
                tree instanceof LambdaExpressionTree || tree instanceof MemberReferenceTree ||
                tree instanceof NewClassTree creation && creation.getClassBody()!=null ||
                tree instanceof BindingPatternTree);
        }

        @Override public Void scan(Tree tree,Void unused) {
            if (tree==null || invalid) return null;
            if (!supports(tree)) {invalid=true;return null;}
            return super.scan(tree,unused);
        }

        @Override public Void visitVariable(VariableTree tree,Void unused) {
            if (trees.getElement(getCurrentPath()) instanceof VariableElement local && local.getKind()==ElementKind.LOCAL_VARIABLE) {
                locals.put(local,locals.size());
                bindings.add("declare:"+local.getSimpleName()+":"+local.asType());
            }
            return super.visitVariable(tree,unused);
        }

        private boolean insideSelectedLoop(boolean breaking) {
            for (TreePath path=getCurrentPath().getParentPath(); path!=null; path=path.getParentPath()) {
                Tree tree=path.getLeaf();
                if (LOOPS.contains(tree.getKind()) || breaking && tree.getKind()==Tree.Kind.SWITCH) {
                    return LOOPS.contains(tree.getKind()) && start(tree)>=from && end(tree)<=to;
                }
                if (tree instanceof MethodTree || tree instanceof LambdaExpressionTree) return false;
            }
            return false;
        }

        @Override public Void visitBreak(BreakTree statement,Void unused) {
            invalid|=statement.getLabel()!=null || !insideSelectedLoop(true);
            return null;
        }

        @Override public Void visitContinue(ContinueTree statement,Void unused) {
            invalid|=statement.getLabel()!=null || !insideSelectedLoop(false);
            return null;
        }

        private boolean written(TreePath path) {
            Tree leaf=path.getLeaf(), parent=path.getParentPath().getLeaf();
            while (parent instanceof ParenthesizedTree) {
                path=path.getParentPath();
                leaf=parent;
                parent=path.getParentPath().getLeaf();
            }
            return parent instanceof AssignmentTree assignment && assignment.getVariable()==leaf ||
                parent instanceof CompoundAssignmentTree compound && compound.getVariable()==leaf ||
                parent instanceof UnaryTree unary && Set.of(Tree.Kind.PREFIX_INCREMENT,Tree.Kind.PREFIX_DECREMENT,
                    Tree.Kind.POSTFIX_INCREMENT,Tree.Kind.POSTFIX_DECREMENT).contains(unary.getKind());
        }

        private void bind() {
            TreePath path = getCurrentPath();
            Element target = trees.getElement(path);
            TypeMirror type = trees.getTypeMirror(path);
            String identity;
            if (path.getLeaf() instanceof IdentifierTree identifier && Set.of("this","super").contains(identifier.getName().toString())) {
                identity=identifier.getName().toString();
            } else if (target instanceof VariableElement local &&
                Set.of(ElementKind.PARAMETER,ElementKind.LOCAL_VARIABLE).contains(local.getKind())) {
                TreePath declaration=trees.getPath(local);
                if (declaration==null || declaration.getCompilationUnit()!=unit || !local.getEnclosingElement().equals(method)) {
                    invalid=true;return;
                }
                int offset=start(declaration.getLeaf());
                if (offset>=from && offset<to && locals.containsKey(local)) identity="local:"+locals.get(local)+":"+local.getSimpleName();
                else if (offset>=0 && offset<from && !written(path) && local.getConstantValue()==null) {
                    captures.putIfAbsent(local,captures.size());
                    identity="capture:"+captures.get(local)+":"+local.getSimpleName();
                } else {invalid=true;return;}
            } else if (target instanceof ExecutableElement executable) identity=SignatureInspector.key(executable);
            else if (target instanceof TypeParameterElement parameter && parameter.getEnclosingElement().equals(method))
                identity="method-type:"+parameter.getSimpleName();
            else if (target instanceof TypeElement resolved) identity=resolved.getQualifiedName().toString();
            else if (target!=null) identity=target.getKind()+":"+target.getEnclosingElement()+":"+target;
            else {invalid=true;return;}
            bindings.add(path.getLeaf().getKind()+":"+identity+":"+type);
        }
        @Override public Void visitIdentifier(IdentifierTree node,Void unused) {bind();return super.visitIdentifier(node,unused);}
        @Override public Void visitMemberSelect(MemberSelectTree node,Void unused) {bind();return super.visitMemberSelect(node,unused);}
        @Override public Void visitMethodInvocation(MethodInvocationTree node,Void unused) {bind();return super.visitMethodInvocation(node,unused);}
        @Override public Void visitNewClass(NewClassTree node,Void unused) {bind();return super.visitNewClass(node,unused);}
    }
}

ExtractionInspector.java:
package rocketbrain.signature;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.lang.model.element.Element;
import javax.lang.model.element.ElementKind;
import javax.lang.model.element.ExecutableElement;
import javax.lang.model.element.Modifier;
import javax.lang.model.element.TypeElement;
import javax.lang.model.element.VariableElement;
import com.sun.source.tree.*;
import com.sun.source.util.JavacTask;
import com.sun.source.util.SourcePositions;
import com.sun.source.util.TreePath;
import com.sun.source.util.TreePathScanner;
import com.sun.source.util.Trees;

import static rocketbrain.signature.SignatureInspector.object;

/** Attributes the declaration and each use introduced by an ordinary JDT extraction. */
final class ExtractionInspector {
    private final JavacTask task;
    private final Trees trees;
    private final SourcePositions positions;
    private final CompilationUnitTree unit;
    private final String source;

    ExtractionInspector(JavacTask task, CompilationUnitTree unit, String source) {
        this.task = task;
        this.trees = Trees.instance(task);
        this.positions = trees.getSourcePositions();
        this.unit = unit;
        this.source = source;
    }

    private int start(Tree tree) { return (int) positions.getStartPosition(unit, tree); }
    private int end(Tree tree) { return (int) positions.getEndPosition(unit, tree); }
    private Map<String,Object> range(Tree tree) { return object("start",start(tree),"end",end(tree)); }
    private boolean token(int offset, String name) {
        int after = offset + name.length();
        return offset >= 0 && after <= source.length() && source.startsWith(name,offset) &&
            (offset == 0 || !Character.isJavaIdentifierPart(source.charAt(offset-1))) &&
            (after == source.length() || !Character.isJavaIdentifierPart(source.charAt(after)));
    }

    private int declarationName(VariableTree tree) {
        String name = tree.getName().toString();
        int from = end(tree.getType()), boundary = tree.getInitializer() == null ? end(tree) : start(tree.getInitializer());
        if (from < 0 || boundary < from) return -1;
        int candidate = source.indexOf(name,from);
        while (candidate >= 0 && candidate < boundary) {
            if (token(candidate,name)) return candidate;
            candidate = source.indexOf(name,candidate+1);
        }
        return -1;
    }

    private int referenceName(ExpressionTree tree, String name) {
        return tree instanceof MemberSelectTree ? end(tree)-name.length() : start(tree);
    }

    private VariableElement binding(int offset, String name) {
        var found = new VariableElement[1];
        new TreePathScanner<Void,Void>() {
            private void remember(int at) {
                if (at == offset && trees.getElement(getCurrentPath()) instanceof VariableElement value && value.getSimpleName().contentEquals(name)) found[0] = value;
            }
            @Override public Void visitVariable(VariableTree tree, Void unused) {
                if (tree.getName().contentEquals(name)) remember(declarationName(tree));
                return super.visitVariable(tree,unused);
            }
            @Override public Void visitIdentifier(IdentifierTree tree, Void unused) {
                if (tree.getName().contentEquals(name)) remember(start(tree));
                return super.visitIdentifier(tree,unused);
            }
            @Override public Void visitMemberSelect(MemberSelectTree tree, Void unused) {
                if (tree.getIdentifier().contentEquals(name)) remember(referenceName(tree,name));
                return super.visitMemberSelect(tree,unused);
            }
        }.scan(unit,null);
        return found[0];
    }

    private TreePath containingStatement(TreePath path) {
        TreePath parent = path.getParentPath();
        Tree value = path.getLeaf();
        if (parent.getLeaf() instanceof ReturnTree statement && statement.getExpression() == value ||
                parent.getLeaf() instanceof VariableTree declaration && declaration.getInitializer() == value &&
                    trees.getElement(parent) instanceof VariableElement variable && variable.getKind() == ElementKind.LOCAL_VARIABLE) {
            return parent.getParentPath().getLeaf() instanceof BlockTree ? parent : null;
        }
        return null;
    }

    Map<String,Object> inspect(String kind, int offset, String name) {
        boolean field = kind.equals("field");
        VariableElement variable = token(offset,name) ? binding(offset,name) : null;
        TreePath declaration = variable == null ? null : trees.getPath(variable);
        if (declaration == null || declaration.getCompilationUnit() != unit || !(declaration.getLeaf() instanceof VariableTree node) ||
                variable.getKind() != (field ? ElementKind.FIELD : ElementKind.LOCAL_VARIABLE) ||
                field && (!variable.getModifiers().contains(Modifier.PRIVATE) || node.getInitializer() != null)) {
            return object("error","Javac could not identify the exact extracted declaration in the current Java file.");
        }
        int nameStart = declarationName(node);
        if (nameStart < 0) return object("error","The introduced Java declaration has no exact name span.");
        var uses = new ArrayList<TreePath>();
        var occupied = new LinkedHashSet<String>();
        new TreePathScanner<Void,Void>() {
            @Override public Void visitVariable(VariableTree tree, Void unused) {
                if (!variable.equals(trees.getElement(getCurrentPath()))) occupied.add(tree.getName().toString());
                return super.visitVariable(tree,unused);
            }
            @Override public Void visitIdentifier(IdentifierTree tree, Void unused) {
                if (variable.equals(trees.getElement(getCurrentPath()))) uses.add(getCurrentPath());
                else occupied.add(tree.getName().toString());
                return super.visitIdentifier(tree,unused);
            }
            @Override public Void visitMemberSelect(MemberSelectTree tree, Void unused) {
                if (variable.equals(trees.getElement(getCurrentPath()))) uses.add(getCurrentPath());
                return super.visitMemberSelect(tree,unused);
            }
        }.scan(unit,null);
        TreePath read = null, write = null;
        ExpressionTree initializer = node.getInitializer();
        for (TreePath use : uses) {
            TreePath parent = use.getParentPath();
            if (field && write == null && parent.getLeaf() instanceof AssignmentTree assignment && assignment.getVariable() == use.getLeaf() &&
                    parent.getParentPath().getLeaf() instanceof ExpressionStatementTree statement && statement.getExpression() == assignment) {
                write = parent.getParentPath();
                initializer = assignment.getExpression();
            } else if (read == null && containingStatement(use) != null) read = use;
            else return object("unsupportedSelection",true,"error","The named extraction must keep exactly one use at the original expression and one evaluation.");
        }
        if (read == null || field && write == null || initializer == null || uses.size() != (field ? 2 : 1)) {
            return object("unsupportedSelection",true,"error","Select a whole return expression or local initializer in a Java block.");
        }
        TreePath statement = containingStatement(read);
        List<? extends StatementTree> block = ((BlockTree) statement.getParentPath().getLeaf()).getStatements();
        int index = block.indexOf(statement.getLeaf());
        Tree introduced = field ? write.getLeaf() : node;
        if (index <= 0 || block.get(index-1) != introduced) return object("unsupportedSelection",true,"error","The extraction must evaluate the expression exactly once in its current block.");
        TreePath method = statement;
        while (method != null && !(method.getLeaf() instanceof MethodTree)) method = method.getParentPath();
        if (method == null || !(trees.getElement(method) instanceof ExecutableElement executable) ||
                !(executable.getEnclosingElement() instanceof TypeElement owner) || owner.getQualifiedName().length() == 0 ||
                field && !owner.equals(variable.getEnclosingElement())) return object("unsupportedSelection",true,"error","Select an expression within a named Java class method.");
        for (Element member : task.getElements().getAllMembers(owner)) {
            if (member.getKind().isField() && !member.equals(variable)) occupied.add(member.getSimpleName().toString());
        }
        var names = new ArrayList<Map<String,Object>>();
        names.add(object("start",nameStart,"end",nameStart+name.length(),"role","declaration"));
        for (TreePath use : uses) {
            int at = referenceName((ExpressionTree)use.getLeaf(),name);
            if (!token(at,name)) return object("error","The extracted binding contains an out-of-range Java name.");
            names.add(object("start",at,"end",at+name.length(),"role",use == read ? "read" : "assignment"));
        }
        names.sort(Comparator.comparingInt(entry -> (int) entry.get("start")));
        return object("kind",kind,"type",variable.asType().toString(),"owner",owner.getQualifiedName().toString(),
            "method",executable.getSimpleName().toString(),"staticField",field && variable.getModifiers().contains(Modifier.STATIC),
            "name",name,"names",names,"occupiedNames",occupied,"declaration",range(node),"initializer",range(initializer),
            "read",range(read.getLeaf()),"assignment",write == null ? null : range(write.getLeaf()));
    }
}

HierarchyInspector.java:
package rocketbrain.signature;

import com.sun.source.tree.*;
import com.sun.source.util.*;
import java.util.*;
import javax.lang.model.element.*;
import javax.lang.model.type.TypeKind;
import javax.lang.model.util.Elements;
import javax.lang.model.util.Types;

/** Source declarations and stable resolved references for reviewed hierarchy moves. */
final class HierarchyInspector {
    private final Trees trees;
    private final DocTrees docs;
    private final Types types;
    private final Elements elements;
    private final SourcePositions positions;

    HierarchyInspector(JavacTask task) {
        trees = Trees.instance(task);
        docs = DocTrees.instance(task);
        types = task.getTypes();
        elements = task.getElements();
        positions = trees.getSourcePositions();
    }

    private String slot(Element member) {
        if (member instanceof VariableElement && member.getKind().isField()) return "F:" + member.getSimpleName();
        if (member instanceof ExecutableElement method && member.getKind() == ElementKind.METHOD) {
            return "M:" + member.getSimpleName() + "(" + String.join(",",method.getParameters().stream()
                .map(parameter -> types.erasure(parameter.asType()).toString()).toList()) + ")";
        }
        return null;
    }

    private static String key(Element element) {
        if (element instanceof VariableElement field && element.getKind().isField() &&
                field.getEnclosingElement() instanceof TypeElement owner) {
            return "F:" + owner.getQualifiedName() + "#" + field.getSimpleName() + ":" + field.asType();
        }
        if (element instanceof ExecutableElement method && method.getEnclosingElement() instanceof TypeElement owner) {
            return owner.getQualifiedName().length() > 0 ? "M:" + SignatureInspector.key(method) :
                "local-method:" + method.getSimpleName() + ":" + method.asType();
        }
        if (element instanceof TypeElement type) return "T:" + type.getQualifiedName();
        if (element instanceof PackageElement pkg) return "P:" + pkg.getQualifiedName();
        return element == null ? "" : element.getKind() + ":" + element.getSimpleName() + ":" + element.asType();
    }

    private List<TypeElement> ancestors(TypeElement start) {
        var seen = new LinkedHashMap<String,TypeElement>();
        var pending = new ArrayDeque<TypeElement>();
        pending.add(start);
        while (!pending.isEmpty()) {
            var current = pending.removeFirst();
            for (var parent : types.directSupertypes(current.asType())) {
                if (types.asElement(parent) instanceof TypeElement declaration &&
                        seen.putIfAbsent(declaration.getQualifiedName().toString(),declaration) == null) {
                    pending.addLast(declaration);
                }
            }
        }
        return new ArrayList<>(seen.values());
    }

    private boolean executable(ExecutableElement method, MethodTree declaration) {
        if (declaration.getBody() == null || method.isVarArgs() || !method.getTypeParameters().isEmpty() ||
                !method.getAnnotationMirrors().isEmpty() || !method.getReturnType().getAnnotationMirrors().isEmpty() ||
                method.getParameters().stream().anyMatch(parameter ->
                    !parameter.getAnnotationMirrors().isEmpty() || !parameter.asType().getAnnotationMirrors().isEmpty())) return false;
        return method.getModifiers().stream().allMatch(modifier ->
            EnumSet.of(Modifier.PUBLIC,Modifier.PROTECTED,Modifier.FINAL).contains(modifier));
    }

    private int commentStart(TreePath declaration, int start, String original) {
        if (docs.getDocCommentTree(declaration) == null) return start;
        int before = original.lastIndexOf("/**",start);
        if (before >= 0) {
            int close = original.indexOf("*/",before);
            if (close >= before && close + 2 <= start && original.substring(close + 2,start).isBlank()) return before;
        }
        return start;
    }

    private Map<String,Object> member(CompilationUnitTree unit, Element element, String source, String uri) {
        final String slot = slot(element);
        var path = trees.getPath(element);
        if (path == null || slot == null) return null;
        var declaration = path.getLeaf();
        long start = positions.getStartPosition(unit,declaration), end = positions.getEndPosition(unit,declaration);
        if (start < 0 || end <= start || end > source.length()) return null;
        boolean movable = false;
        String constant = null;
        if (element instanceof ExecutableElement method && declaration instanceof MethodTree tree) {
            movable = executable(method,tree);
        } else if (element instanceof VariableElement field && declaration instanceof VariableTree tree) {
            Object value = field.getConstantValue();
            movable = value != null && field.getModifiers().containsAll(Set.of(Modifier.STATIC,Modifier.FINAL)) &&
                !field.getModifiers().contains(Modifier.PRIVATE) && field.getAnnotationMirrors().isEmpty() &&
                field.asType().getAnnotationMirrors().isEmpty() && tree.getInitializer() != null;
            if (value != null) constant = value.getClass().getName() + ":" + value.toString();
        }
        return SignatureInspector.object("key",key(element),"slot",slot,"name",element.getSimpleName().toString(),
            "uri",uri,"start",start,"end",end,"commentStart",commentStart(path,(int)start,source),"movable",movable,
            "type",element.asType().toString(),"modifiers",SignatureInspector.modifiers(element),"constant",constant);
    }

    private Map<String,Object> type(CompilationUnitTree unit, TypeElement element, ClassTree node, String uri, String text) {
        long start = positions.getStartPosition(unit,node),end = positions.getEndPosition(unit,node);
        if (start < 0 || end <= start || end > text.length()) return null;
        var ancestorTypes = ancestors(element);
        var slots = new TreeSet<String>();
        for (var parent : ancestorTypes) {
            for (var inherited : parent.getEnclosedElements()) {
                String inheritedSlot = slot(inherited);
                if (inheritedSlot != null) slots.add(inheritedSlot);
            }
        }
        String superclass = element.getSuperclass().getKind() == TypeKind.DECLARED &&
                types.asElement(element.getSuperclass()) instanceof TypeElement parent ? parent.getQualifiedName().toString() : "";
        boolean plain = element.getKind() == ElementKind.CLASS && element.getNestingKind() == NestingKind.TOP_LEVEL &&
            element.getTypeParameters().isEmpty() && element.getAnnotationMirrors().isEmpty() && element.getInterfaces().isEmpty() &&
            !element.getModifiers().contains(Modifier.SEALED) && !element.getModifiers().contains(Modifier.NON_SEALED) &&
            (superclass.isEmpty() || superclass.equals(element.getSuperclass().toString()));
        var members = new ArrayList<Map<String,Object>>();
        for (var declaration : element.getEnclosedElements()) {
            var item = member(unit,declaration,text,uri);
            if (item != null) members.add(item);
        }
        return SignatureInspector.object("id",element.getQualifiedName().toString(),"name",element.getSimpleName().toString(),
            "uri",uri,"start",start,"end",end,"package",elements.getPackageOf(element).getQualifiedName().toString(),
            "superclass",superclass,"ancestors",ancestorTypes.stream().map(item -> item.getQualifiedName().toString()).toList(),
            "inheritedSlots",slots,"members",members,"plain",plain);
    }

    Map<String,Object> inspect(List<CompilationUnitTree> units, Map<String,SignatureInspector.Source> sources) {
        var declarations = new ArrayList<Map<String,Object>>();
        var files = new ArrayList<Map<String,Object>>();
        int totalEvents = 0;
        for (var unit : units) {
            String uri = unit.getSourceFile().toUri().toString(), text = sources.get(uri).text;
            var events = new ArrayList<Map<String,Object>>();
            new TreePathScanner<Void,Void>() {
                @Override public Void visitClass(ClassTree node, Void unused) {
                    if (trees.getElement(getCurrentPath()) instanceof TypeElement element && !element.getQualifiedName().isEmpty()) {
                        var item = type(unit,element,node,uri,text);
                        if (item != null) declarations.add(item);
                    }
                    return super.visitClass(node,unused);
                }
                void event(Tree node) {
                    long start = positions.getStartPosition(unit,node),end = positions.getEndPosition(unit,node);
                    if (start < 0 || end <= start || end > text.length()) return;
                    var path = getCurrentPath();
                    var mirror = trees.getTypeMirror(path);
                    var element = trees.getElement(path);
                    String receiver = node instanceof IdentifierTree identifier &&
                        (identifier.getName().contentEquals("this") || identifier.getName().contentEquals("super")) ?
                        identifier.getName().toString() : node instanceof MemberSelectTree select &&
                          (select.getIdentifier().contentEquals("this") || select.getIdentifier().contentEquals("super")) ?
                          select.getIdentifier().toString() : "";
                    events.add(SignatureInspector.object("start",start,"end",end,"kind",node.getKind().name(),
                        "key",key(element),"type",mirror == null ? "" : mirror.toString(),"receiver",receiver));
                }
                @Override public Void visitIdentifier(IdentifierTree tree, Void unused) { event(tree); return super.visitIdentifier(tree,unused); }
                @Override public Void visitMemberSelect(MemberSelectTree tree, Void unused) { event(tree); return super.visitMemberSelect(tree,unused); }
                @Override public Void visitMethodInvocation(MethodInvocationTree tree, Void unused) { event(tree); return super.visitMethodInvocation(tree,unused); }
                @Override public Void visitNewClass(NewClassTree tree, Void unused) { event(tree); return super.visitNewClass(tree,unused); }
                @Override public Void visitMemberReference(MemberReferenceTree tree, Void unused) { event(tree); return super.visitMemberReference(tree,unused); }
            }.scan(unit,null);
            if ((totalEvents += events.size()) > 24000 || declarations.size() > 350) {
                throw new IllegalArgumentException("The Java hierarchy proof exceeds its declaration or reference limit.");
            }
            files.add(SignatureInspector.object("uri",uri,"events",events));
        }
        return SignatureInspector.object("classes",declarations,"files",files);
    }
}

InlineMethodInspector.java:
package rocketbrain.signature;

import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.lang.model.element.Element;
import javax.lang.model.element.ElementKind;
import javax.lang.model.element.ExecutableElement;
import javax.lang.model.element.Modifier;
import javax.lang.model.element.TypeElement;
import javax.lang.model.element.VariableElement;
import javax.lang.model.type.TypeMirror;
import com.sun.source.tree.*;
import com.sun.source.util.JavacTask;
import com.sun.source.util.SourcePositions;
import com.sun.source.util.TreePath;
import com.sun.source.util.TreePathScanner;
import com.sun.source.util.Trees;

import static rocketbrain.signature.SignatureInspector.object;

/** Attributes one call and checks the argument/parameter bindings of its reviewed replacement. */
final class InlineMethodInspector {
    private static final Set<Modifier> MODIFIERS = Set.of(Modifier.PRIVATE,Modifier.STATIC,Modifier.FINAL);
    private final Trees trees;
    private final SourcePositions positions;
    private final CompilationUnitTree unit;
    private final String source;

    InlineMethodInspector(JavacTask task, CompilationUnitTree unit, String source) {
        this.trees = Trees.instance(task);
        this.positions = trees.getSourcePositions();
        this.unit = unit;
        this.source = source;
    }

    private int start(Tree tree) { return (int)positions.getStartPosition(unit,tree); }
    private int end(Tree tree) { return (int)positions.getEndPosition(unit,tree); }
    private Map<String,Object> range(Tree tree) { return object("start",start(tree),"end",end(tree)); }
    private Map<String,Object> error(String message) { return object("error",message); }

    private String supportedType(TypeMirror type) {
        if (type == null) return null;
        String name = type.toString();
        return type.getKind().isPrimitive() && type.getAnnotationMirrors().isEmpty() || name.equals("java.lang.String") ? name : null;
    }

    private TreePath placement(TreePath expression) {
        TreePath statement = expression.getParentPath();
        while (statement != null && statement.getLeaf() instanceof ParenthesizedTree) statement = statement.getParentPath();
        if (statement == null || statement.getParentPath() == null || !(statement.getParentPath().getLeaf() instanceof BlockTree)) return null;
        Tree leaf = statement.getLeaf();
        if (leaf instanceof ReturnTree) return statement;
        if (leaf instanceof VariableTree variable && trees.getElement(statement) instanceof VariableElement local &&
                local.getKind() == ElementKind.LOCAL_VARIABLE && variable.getInitializer() != null) {
            int from=start(variable), to=end(variable);
            if (from<0 || to<=from || source.charAt(to-1)!=';') return null;
            var siblings=((BlockTree)statement.getParentPath().getLeaf()).getStatements();
            for (StatementTree sibling:siblings) {
                if (sibling!=variable && sibling instanceof VariableTree && start(sibling)<to && end(sibling)>from) return null;
            }
            return statement;
        }
        return null;
    }

    private ExecutableElement caller(TreePath path) {
        for (TreePath current=path;current!=null;current=current.getParentPath()) {
            if (current.getLeaf() instanceof LambdaExpressionTree) return null;
            if (current.getLeaf() instanceof MethodTree && trees.getElement(current) instanceof ExecutableElement method) return method;
        }
        return null;
    }

    private String siteType(TreePath statement, ExecutableElement caller) {
        if (statement.getLeaf() instanceof VariableTree) return trees.getElement(statement).asType().toString();
        return caller.getReturnType().toString();
    }

    private boolean supportsExpressionNode(Tree tree) {
        return switch (tree.getKind()) {
            case IDENTIFIER, PARENTHESIZED, CONDITIONAL_EXPRESSION, TYPE_CAST, PRIMITIVE_TYPE,
                 INT_LITERAL, LONG_LITERAL, FLOAT_LITERAL, DOUBLE_LITERAL, BOOLEAN_LITERAL, CHAR_LITERAL,
                 STRING_LITERAL, NULL_LITERAL, PLUS, MINUS, MULTIPLY, DIVIDE, REMAINDER, LEFT_SHIFT,
                 RIGHT_SHIFT, UNSIGNED_RIGHT_SHIFT, LESS_THAN, LESS_THAN_EQUAL, GREATER_THAN,
                 GREATER_THAN_EQUAL, EQUAL_TO, NOT_EQUAL_TO, AND, OR, XOR, CONDITIONAL_AND,
                 CONDITIONAL_OR, UNARY_PLUS, UNARY_MINUS, BITWISE_COMPLEMENT, LOGICAL_COMPLEMENT -> true;
            default -> false;
        };
    }

    private List<Map<String,Object>> bodyReferences(TreePath expression, List<? extends VariableElement> formals) {
        if (!supportsExpressionNode(expression.getLeaf())) return null;
        var references = new ArrayList<Map<String,Object>>();
        boolean[] valid = {true};
        new TreePathScanner<Void,Void>() {
            @Override public Void scan(Tree tree, Void unused) {
                if (tree == null || !valid[0]) return null;
                if (!supportsExpressionNode(tree)) { valid[0]=false; return null; }
                return super.scan(tree,unused);
            }

            @Override public Void visitIdentifier(IdentifierTree tree, Void unused) {
                int ordinal = formals.indexOf(trees.getElement(getCurrentPath()));
                int from=start(tree), to=end(tree);
                if (ordinal<0 || from<0 || to<=from || !source.substring(from,to).contentEquals(tree.getName())) {
                    valid[0]=false;
                    return null;
                }
                references.add(object("index",ordinal,"start",from,"end",to));
                return null;
            }

            @Override public Void visitTypeCast(TypeCastTree tree, Void unused) {
                if (!(tree.getType() instanceof PrimitiveTypeTree)) { valid[0]=false; return null; }
                return super.visitTypeCast(tree,unused);
            }
        }.scan(expression,null);
        return valid[0] ? references : null;
    }

    private String binding(Element element) {
        if (element == null) return "";
        var parts = new ArrayList<String>();
        for (Element current=element; current!=null; current=current.getEnclosingElement()) {
            if (current instanceof TypeElement type) {
                parts.add(type.getQualifiedName().toString());
                break;
            }
            parts.add(current.getKind()+":"+current.toString()+":"+current.asType().toString());
        }
        return String.join("|",parts);
    }

    private Map<String,Object> argument(TreePath expression) {
        var references=new ArrayList<String>();
        new TreePathScanner<Void,Void>() {
            private void record() { references.add(binding(trees.getElement(getCurrentPath()))); }
            @Override public Void visitIdentifier(IdentifierTree tree,Void unused) { record(); return super.visitIdentifier(tree,unused); }
            @Override public Void visitMemberSelect(MemberSelectTree tree,Void unused) { record(); return super.visitMemberSelect(tree,unused); }
            @Override public Void visitNewClass(NewClassTree tree,Void unused) { record(); return super.visitNewClass(tree,unused); }
            @Override public Void visitMemberReference(MemberReferenceTree tree,Void unused) { record(); return super.visitMemberReference(tree,unused); }
        }.scan(expression,null);
        return object("type",trees.getTypeMirror(expression).toString(),"bindings",references);
    }

    private Set<String> usedNames() {
        var names = new LinkedHashSet<String>();
        new TreePathScanner<Void,Void>() {
            @Override public Void visitVariable(VariableTree tree,Void unused) {
                names.add(tree.getName().toString()); return super.visitVariable(tree,unused);
            }
            @Override public Void visitIdentifier(IdentifierTree tree,Void unused) {
                names.add(tree.getName().toString()); return super.visitIdentifier(tree,unused);
            }
        }.scan(unit,null);
        return names;
    }

    private Map<String,Object> plan(int from,int to) {
        var matches=new ArrayList<TreePath>();
        new TreePathScanner<Void,Void>() {
            @Override public Void visitMethodInvocation(MethodInvocationTree call,Void unused) {
                Tree select=call.getMethodSelect();
                boolean atName=from==to && start(select)<=from && from<end(select) || from==start(select) && to==end(select);
                if (atName || from==start(call) && to==end(call)) matches.add(getCurrentPath());
                return super.visitMethodInvocation(call,unused);
            }
        }.scan(unit,null);
        if (matches.size()!=1) return error("Select one complete Java method call or put the cursor on its name.");
        TreePath selected=matches.get(0), statement=placement(selected);
        ExecutableElement caller=caller(selected);
        if (statement==null || caller==null) return error("Select the whole return expression or a local initializer in an ordinary Java method block.");
        MethodInvocationTree call=(MethodInvocationTree)selected.getLeaf();
        if (!(call.getMethodSelect() instanceof IdentifierTree) || !call.getTypeArguments().isEmpty() ||
                !(trees.getElement(selected) instanceof ExecutableElement target) || !caller.getEnclosingElement().equals(target.getEnclosingElement()) ||
                !(target.getEnclosingElement() instanceof TypeElement owner) || owner.getQualifiedName().length()==0 || !target.getModifiers().containsAll(Set.of(Modifier.PRIVATE,Modifier.STATIC)) ||
                !MODIFIERS.containsAll(target.getModifiers()) || target.isVarArgs() || !target.getTypeParameters().isEmpty() ||
                !target.getThrownTypes().isEmpty() || !target.getAnnotationMirrors().isEmpty() || target.equals(caller)) {
            return error("Inline a non-recursive private static method declared in the same class.");
        }
        TreePath declaration=trees.getPath(target);
        if (declaration==null || declaration.getCompilationUnit()!=unit || !(declaration.getLeaf() instanceof MethodTree method) ||
                method.getBody()==null || method.getBody().getStatements().size()!=1 ||
                !(method.getBody().getStatements().get(0) instanceof ReturnTree returned) || returned.getExpression()==null) {
            return error("The selected method must have one return expression in this Java file.");
        }
        var formals=target.getParameters();
        String resultType=supportedType(target.getReturnType());
        if (resultType==null || formals.size()>16 || formals.size()!=call.getArguments().size()) return error("Use a primitive or String method with up to sixteen arguments.");
        TreePath body=TreePath.getPath(declaration,returned.getExpression());
        var references=bodyReferences(body,formals);
        if (references==null) return error("Inline return expressions made from literals, parameters and supported Java operators.");
        var arguments=new ArrayList<Map<String,Object>>();
        for (int index=0;index<formals.size();index++) {
            VariableElement parameter=formals.get(index);
            String type=supportedType(parameter.asType());
            if (type==null || !parameter.getAnnotationMirrors().isEmpty()) return error("Use primitive or String parameters without annotations.");
            ExpressionTree expression=call.getArguments().get(index);
            arguments.add(object("type",type,"range",range(expression),"expression",argument(new TreePath(selected,expression))));
        }
        return object("method",target.getSimpleName().toString(),"owner",owner.getQualifiedName().toString(),"type",resultType,
                "siteType",siteType(statement,caller),"caller",binding(caller),"call",range(call),"statement",range(statement.getLeaf()),
                "body",range(returned.getExpression()),"arguments",arguments,"references",references,"usedNames",usedNames());
    }

    private Map<String,Object> check(int from,int to,int count) {
        var matches=new ArrayList<TreePath>();
        new TreePathScanner<Void,Void>() {
            @Override public Void visitTypeCast(TypeCastTree tree,Void unused) {
                if (from==start(tree) && to==end(tree)) matches.add(getCurrentPath());
                return super.visitTypeCast(tree,unused);
            }
        }.scan(unit,null);
        if (matches.size()!=1) return error("Javac could not verify the replacement's return conversion.");
        TreePath selected=matches.get(0), statement=placement(selected);
        ExecutableElement caller=caller(selected);
        if (statement==null || caller==null) return error("The replacement left the reviewed Java statement.");
        if (statement.getLeaf() instanceof VariableTree && trees.getElement(statement) instanceof VariableElement variable && variable.getConstantValue()!=null) {
            return error("This inline edit would change the original local into a compile-time constant.");
        }
        var siblings=((BlockTree)statement.getParentPath().getLeaf()).getStatements();
        int index=siblings.indexOf(statement.getLeaf());
        if (index<count) return error("The evaluated arguments are missing from the reviewed Java statement.");
        var locals=new ArrayList<VariableElement>();
        var arguments=new ArrayList<Map<String,Object>>();
        for (int i=index-count;i<index;i++) {
            if (!(siblings.get(i) instanceof VariableTree variable) || variable.getInitializer()==null) return error("An argument is not evaluated immediately before the replacement.");
            TreePath local=new TreePath(statement.getParentPath(),variable);
            if (!(trees.getElement(local) instanceof VariableElement element) || element.getKind()!=ElementKind.LOCAL_VARIABLE ||
                    element.getModifiers().contains(Modifier.FINAL)) return error("The argument must retain an independent, nonconstant Java binding.");
            locals.add(element);
            arguments.add(object("name",element.getSimpleName().toString(),"type",supportedType(element.asType()),
                    "expression",argument(new TreePath(local,variable.getInitializer()))));
        }
        var expression=((TypeCastTree)selected.getLeaf()).getExpression();
        var references=bodyReferences(new TreePath(selected,expression),locals);
        if (references==null) return error("The replacement expression does not bind to its exact evaluated arguments.");
        return object("type",supportedType(trees.getTypeMirror(selected)),"siteType",siteType(statement,caller),"caller",binding(caller),
                "arguments",arguments,"references",references.stream().map(record->record.get("index")).toList());
    }

    Map<String,Object> inspect(int from,int to,int argumentCount) {
        return argumentCount<0 ? plan(from,to) : check(from,to,argumentCount);
    }
}

SignatureInspector.java:
package rocketbrain.signature;

import java.io.*;
import java.net.URI;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import javax.lang.model.element.*;
import javax.lang.model.type.TypeKind;
import javax.lang.model.util.Elements;
import javax.lang.model.util.Types;
import javax.tools.*;
import com.sun.source.tree.*;
import com.sun.source.util.*;

/** Owned read-only compiler attribution. No class generation, plugins or processors. */
public final class SignatureInspector {
    static final class Source extends SimpleJavaFileObject {
        final String text;
        Source(String uri, String text) { super(URI.create(uri), Kind.SOURCE); this.text = text; }
        public CharSequence getCharContent(boolean ignoreErrors) { return text; }
    }
    static String key(ExecutableElement method) {
        TypeElement owner = (TypeElement) method.getEnclosingElement();
        return owner.getQualifiedName() + "#" + method.getSimpleName() + "(" + String.join(",", method.getParameters().stream().map(p -> p.asType().toString()).toList()) + ")";
    }
    static String json(Object value) {
        if (value == null) return "null";
        if (value instanceof Boolean || value instanceof Number) return value.toString();
        if (value instanceof Map<?, ?> map) return "{" + String.join(",", map.entrySet().stream().map(e -> json(e.getKey().toString()) + ":" + json(e.getValue())).toList()) + "}";
        if (value instanceof Collection<?> list) return "[" + String.join(",", list.stream().map(SignatureInspector::json).toList()) + "]";
        String s = value.toString(); StringBuilder out = new StringBuilder("\"");
        for (int i = 0; i < s.length(); i++) { char c = s.charAt(i); if (c == '\\' || c == '"') out.append('\\').append(c); else if (c < 32) out.append(String.format("\\u%04x", (int)c)); else out.append(c); }
        return out.append('"').toString();
    }
    static Map<String, Object> object(Object... values) {
        Map<String, Object> map = new LinkedHashMap<>(); for (int i = 0; i < values.length; i += 2) map.put((String) values[i], values[i + 1]); return map;
    }
    static List<Map<String,Object>> typeParameters(List<? extends TypeParameterElement> parameters) {
        return parameters.stream().map(p -> object("name",p.getSimpleName().toString(),"bounds",p.getBounds().stream().map(Object::toString).toList())).toList();
    }
    static final class Method {
        ExecutableElement element; MethodTree tree; CompilationUnitTree unit; String uri; long start, end, nameStart;
        Map<String, Object> model; List<Map<String, Object>> parameters = new ArrayList<>(); Set<String> identifiers = new TreeSet<>();
    }
    static boolean safeArgument(TreePath parent, ExpressionTree value, Trees trees) {
        if (value instanceof LiteralTree) return true;
        if (value instanceof UnaryTree unary && unary.getKind() == Tree.Kind.UNARY_MINUS && unary.getExpression() instanceof LiteralTree) return true;
        if (value instanceof IdentifierTree) {
            Element element = trees.getElement(new TreePath(parent, value));
            return element instanceof VariableElement variable && (Set.of(ElementKind.LOCAL_VARIABLE, ElementKind.PARAMETER, ElementKind.EXCEPTION_PARAMETER, ElementKind.RESOURCE_VARIABLE).contains(variable.getKind()) || variable.getConstantValue() != null);
        }
        return false;
    }
    static List<Map<String,Object>> errors(DiagnosticCollector<JavaFileObject> diagnostics) {
        return diagnostics.getDiagnostics().stream().filter(d -> d.getKind() == Diagnostic.Kind.ERROR).limit(30)
            .map(d -> object("uri",d.getSource() == null ? null : d.getSource().toUri().toString(),
                "start",d.getStartPosition(),"end",d.getEndPosition(),"code",d.getCode(),"message",d.getMessage(Locale.ROOT))).toList();
    }

    static Map<String,Object> location(CompilationUnitTree unit, Tree node, SourcePositions positions) {
        return object("uri",unit.getSourceFile().toUri().toString(),"start",positions.getStartPosition(unit,node),
            "end",positions.getEndPosition(unit,node));
    }

    static List<Map<String,Object>> diagrams(List<CompilationUnitTree> units, Trees trees, Types types) {
        SourcePositions positions = trees.getSourcePositions();
        List<Map<String,Object>> declarations = new ArrayList<>();
        for (var unit : units) {
            new TreePathScanner<Void,Void>() {
                @Override public Void visitClass(ClassTree node, Void unused) {
                    var bound = trees.getElement(getCurrentPath());
                    if (!(bound instanceof TypeElement declared) ||
                            (declared.getNestingKind() != NestingKind.TOP_LEVEL && declared.getNestingKind() != NestingKind.MEMBER)) {
                        return super.visitClass(node,unused);
                    }
                    List<Map<String,Object>> members = new ArrayList<>(), relations = new ArrayList<>();
                    int omittedMembers = 0;
                    for (var parent : types.directSupertypes(declared.asType())) {
                        if (!(types.asElement(parent) instanceof TypeElement owner)) continue;
                        boolean contract = owner.getKind().isInterface();
                        if (!contract && node.getExtendsClause() == null) continue;
                        relations.add(object("target",owner.getQualifiedName().toString(),
                            "kind",contract && !declared.getKind().isInterface() ? "implements" : "extends",
                            "signature",parent.toString()));
                    }
                    Element enclosing = declared.getEnclosingElement();
                    if (enclosing instanceof TypeElement container) {
                        relations.add(object("target",container.getQualifiedName().toString(),"kind","nestedIn",
                            "signature",container.getQualifiedName().toString()));
                    }
                    for (var member : declared.getEnclosedElements()) {
                        var memberPath = trees.getPath(member);
                        if (memberPath == null) continue;
                        var ownerUnit = memberPath.getCompilationUnit();
                        var declaration = memberPath.getLeaf();
                        var anchor = location(ownerUnit,declaration,positions);
                        if ((long) anchor.get("start") < 0 || (long) anchor.get("end") < 0) continue;
                        if (members.size() >= 80) { omittedMembers++; continue; }
                        if (member instanceof VariableElement field && field.getKind().isField()) {
                            members.add(object("name",field.getSimpleName().toString(),"signature",field.asType().toString(),
                                "kind","field","modifiers",modifiers(field),"location",anchor));
                        } else if (member instanceof ExecutableElement method) {
                            boolean ctor = method.getKind() == ElementKind.CONSTRUCTOR;
                            String memberName = ctor ? declared.getSimpleName().toString() : method.getSimpleName().toString();
                            members.add(object("name",memberName,"signature",memberName + "(" +
                                String.join(", ",method.getParameters().stream().map(p -> p.asType().toString()).toList()) + ")"
                                + (ctor ? "" : " : " + method.getReturnType()),
                                "kind",ctor ? "constructor" : "method","modifiers",modifiers(method),"location",anchor));
                        }
                    }
                    declarations.add(object("id",declared.getQualifiedName().toString(),
                        "name",declared.getSimpleName().toString(),"kind",declared.getKind().toString(),
                        "modifiers",modifiers(declared),"location",location(unit,node,positions),
                        "relations",relations,"members",members,"omittedMembers",omittedMembers));
                    if (declarations.size() > 300) throw new IllegalArgumentException("Java diagram declaration limit");
                    return super.visitClass(node,unused);
                }
            }.scan(unit,null);
        }
        return declarations;
    }

    static List<String> modifiers(Element element) {
        return element.getModifiers().stream().map(Object::toString).sorted().toList();
    }

    static final class Flow {
        private record Event(int id, String kind, String name, int start, int end, List<Integer> inputs) {}
        final Map<Element,Integer> definitions = new HashMap<>();
        final List<Event> events = new ArrayList<>();
        final CompilationUnitTree unit;
        final Trees trees;
        final SourcePositions positions;
        final String text;

        Flow(CompilationUnitTree unit, Trees trees, String text) {
            this.unit = unit;
            this.trees = trees;
            this.positions = trees.getSourcePositions();
            this.text = text;
        }
        UnsupportedOperationException outsideScope() {
            return new UnsupportedOperationException("Trace a straight-line method with initialized local primitive or String values, simple assignments and returns.");
        }
        int add(String kind, String name, int start, int end, List<Integer> inputs) {
            if (events.size() >= 700 || start < 0 || end <= start || end > text.length()) throw outsideScope();
            int index = events.size();
            events.add(new Event(index,kind,name,start,end,List.copyOf(inputs)));
            return index;
        }
        int start(Tree node) { return (int) positions.getStartPosition(unit,node); }
        int end(Tree node) { return (int) positions.getEndPosition(unit,node); }

        VariableElement variable(TreePath route) {
            Element value = trees.getElement(route);
            if (!(value instanceof VariableElement local) ||
                    (local.getKind() != ElementKind.LOCAL_VARIABLE && local.getKind() != ElementKind.PARAMETER) ||
                    (!local.asType().getKind().isPrimitive() && !local.asType().toString().equals("java.lang.String"))) {
                throw outsideScope();
            }
            return local;
        }

        int nameAt(VariableTree tree) {
            String name = tree.getName().toString();
            int low = start(tree);
            int until = tree.getInitializer() == null ? end(tree) : start(tree.getInitializer());
            if (low < 0 || until < low || until > text.length()) throw outsideScope();
            var matcher = java.util.regex.Pattern.compile("/\\*[\\s\\S]*?\\*/|//[^\\r\\n]*|"
                + "\"(?:\\\\.|[^\"\\\\])*\"|'(?:\\\\.|[^'\\\\])*'|[\\p{javaJavaIdentifierStart}][\\p{javaJavaIdentifierPart}]*")
                .matcher(text);
            matcher.region(low,until);
            int found = -1;
            while (matcher.find()) if (matcher.group().equals(name)) found = matcher.start();
            if (found < 0) throw outsideScope();
            return found;
        }

        void declaration(TreePath at, VariableTree tree, boolean parameter) {
            VariableElement value = variable(at);
            if (!parameter && tree.getInitializer() == null) throw outsideScope();
            List<Integer> inputs = parameter ? List.of() : expression(new TreePath(at,tree.getInitializer()));
            int offset = nameAt(tree);
            definitions.put(value,add(parameter ? "parameter" : "definition",value.getSimpleName().toString(),
                offset,offset + tree.getName().length(),inputs));
        }

        List<Integer> expression(TreePath route) {
            Tree leaf = route.getLeaf();
            return switch (leaf.getKind()) {
                case BOOLEAN_LITERAL, CHAR_LITERAL, DOUBLE_LITERAL, FLOAT_LITERAL, INT_LITERAL, LONG_LITERAL,
                     STRING_LITERAL, NULL_LITERAL -> {
                    int from = start(leaf), to = end(leaf);
                    String value = text.substring(from,to);
                    yield List.of(add("literal",value.length() > 60 ? value.substring(0,57) + "..." : value,from,to,List.of()));
                }
                case IDENTIFIER -> {
                    VariableElement local = variable(route);
                    Integer from = definitions.get(local);
                    if (from == null) throw outsideScope();
                    yield List.of(add("read",local.getSimpleName().toString(),start(leaf),end(leaf),List.of(from)));
                }
                case PARENTHESIZED -> expression(new TreePath(route,((ParenthesizedTree) leaf).getExpression()));
                case TYPE_CAST -> expression(new TreePath(route,((TypeCastTree) leaf).getExpression()));
                case LOGICAL_COMPLEMENT, UNARY_MINUS, UNARY_PLUS, BITWISE_COMPLEMENT ->
                    expression(new TreePath(route,((UnaryTree) leaf).getExpression()));
                case PLUS, MINUS, MULTIPLY, DIVIDE, REMAINDER, LEFT_SHIFT, RIGHT_SHIFT, UNSIGNED_RIGHT_SHIFT,
                     LESS_THAN, LESS_THAN_EQUAL, GREATER_THAN, GREATER_THAN_EQUAL, EQUAL_TO, NOT_EQUAL_TO,
                     AND, OR, XOR -> {
                    BinaryTree binary = (BinaryTree) leaf;
                    List<Integer> inputs = new ArrayList<>(expression(new TreePath(route,binary.getLeftOperand())));
                    inputs.addAll(expression(new TreePath(route,binary.getRightOperand())));
                    yield inputs;
                }
                default -> throw outsideScope();
            };
        }

        List<Map<String,Object>> trace(TreePath methodPath) {
            MethodTree node = (MethodTree) methodPath.getLeaf();
            for (VariableTree parameter : node.getParameters()) declaration(new TreePath(methodPath,parameter),parameter,true);
            TreePath body = new TreePath(methodPath,node.getBody());
            for (StatementTree statement : node.getBody().getStatements()) {
                TreePath line = new TreePath(body,statement);
                if (statement instanceof VariableTree local) {
                    declaration(line,local,false);
                } else if (statement instanceof ExpressionStatementTree expr && expr.getExpression() instanceof AssignmentTree assignment
                        && assignment.getVariable() instanceof IdentifierTree target) {
                    TreePath operation = new TreePath(line,assignment);
                    var variable = variable(new TreePath(operation,target));
                    List<Integer> inputs = expression(new TreePath(operation,assignment.getExpression()));
                    definitions.put(variable,add("assignment",variable.getSimpleName().toString(),start(target),end(target),inputs));
                } else if (statement instanceof ReturnTree returned && returned.getExpression() != null) {
                    List<Integer> inputs = expression(new TreePath(line,returned.getExpression()));
                    add("return","return",start(returned),start(returned) + 6,inputs);
                } else if (statement.getKind() != Tree.Kind.EMPTY_STATEMENT) {
                    throw outsideScope();
                }
            }
            return events.stream().map(event -> object("id",event.id(),"kind",event.kind(),"name",event.name(),
                "start",event.start(),"end",event.end(),"inputs",event.inputs())).toList();
        }
    }

    static Map<String,Object> dataFlow(List<CompilationUnitTree> units, Trees trees, Map<String,Source> sources, String uri, int offset) {
        for (var unit : units) {
            if (!unit.getSourceFile().toUri().toString().equals(uri)) continue;
            var selected = new TreePath[1];
            var positions = trees.getSourcePositions();
            new TreePathScanner<Void,Void>() {
                @Override public Void visitMethod(MethodTree method, Void unused) {
                    if (method.getBody() != null && positions.getStartPosition(unit,method) <= offset
                            && positions.getEndPosition(unit,method) > offset) {
                        selected[0] = getCurrentPath();
                    }
                    return super.visitMethod(method,unused);
                }
            }.scan(unit,null);
            if (selected[0] == null) return object("error","Place the cursor in a Java method.");
            try {
                var events = new Flow(unit,trees,sources.get(uri).text).trace(selected[0]);
                return object("uri",uri,"events",events);
            } catch (UnsupportedOperationException outside) {
                return object("error",outside.getMessage());
            }
        }
        return object("error","The selected Java source is outside the compiler scope.");
    }

    static Map<String,Object> typeImport(CompilationUnitTree unit,Trees trees,int from,int to,String expected) {
        var positions=trees.getSourcePositions();
        var bindings=new ArrayList<Map<String,Object>>();
        String[] selected={null};
        String simple=expected.substring(expected.lastIndexOf('.')+1);
        new TreePathScanner<Void,Void>() {
            @Override public Void visitIdentifier(IdentifierTree tree,Void unused) {
                if(tree.getName().contentEquals(simple)&&trees.getElement(getCurrentPath()) instanceof TypeElement type) {
                    long start=positions.getStartPosition(unit,tree),end=positions.getEndPosition(unit,tree);
                    String qualified=type.getQualifiedName().toString();
                    bindings.add(object("start",start,"end",end,"type",qualified));
                    if(start==from&&end==to)selected[0]=qualified;
                }
                return super.visitIdentifier(tree,unused);
            }
        }.scan(unit,null);
        return object("target",selected[0],"bindings",bindings);
    }

    public static void main(String[] args) throws Exception {
        if (args.length != 4 && !(args.length == 5 && Set.of("diagram","hierarchy").contains(args[4])) &&
                !(args.length == 7 && args[4].equals("dataflow")) &&
                !(args.length == 6 && args[4].equals("conversion")) &&
                !(args.length == 9 && args[4].equals("constant")) &&
                !(args.length == 9 && args[4].equals("extraction")) &&
                !(args.length == 9 && args[4].equals("methodInline")) &&
                !(args.length == 8 && args[4].equals("typeStructure")) &&
                !(args.length == 10 && args[4].equals("methodExtract")) &&
                !(args.length == 9 && Set.of("typeImport", "staticImport").contains(args[4])) &&
                !(args.length == 5 && args[4].equals("check")) &&
                !(args.length >= 9 && args.length <= 57 && (args.length - 9) % 3 == 0 && args[4].equals("structural"))) {
            throw new IllegalArgumentException("Use classpath-file, source-list, empty-provider-path and release.");
        }
        String classpath = Files.readString(Path.of(args[0]), StandardCharsets.UTF_8);
        List<Source> sources = new ArrayList<>(); Map<String, Source> byUri = new HashMap<>();
        for (String line : Files.readAllLines(Path.of(args[1]), StandardCharsets.UTF_8)) {
            String[] parts = line.split("\t", -1); if (parts.length != 2 || sources.size() >= 500) throw new IllegalArgumentException("Invalid bounded source list.");
            Source source = new Source(parts[0], new String(Base64.getDecoder().decode(parts[1]), StandardCharsets.UTF_8)); sources.add(source); byUri.put(source.toUri().toString(), source);
        }
        JavaCompiler compiler = ToolProvider.getSystemJavaCompiler(); if (compiler == null) throw new IllegalStateException("A full independent JDK is required.");
        DiagnosticCollector<JavaFileObject> diagnostics = new DiagnosticCollector<>();
        boolean namedModule = sources.stream().anyMatch(source -> source.toUri().getPath().endsWith("/module-info.java"));
        try (StandardJavaFileManager standard = compiler.getStandardFileManager(diagnostics, Locale.ROOT, StandardCharsets.UTF_8)) {
            JavaFileManager files = new ForwardingJavaFileManager<StandardJavaFileManager>(standard) {
                public JavaFileObject getJavaFileForOutput(Location location, String name, JavaFileObject.Kind kind, FileObject sibling) throws IOException { throw new IOException("Class generation is disabled."); }
                @Override
                public boolean contains(Location location, FileObject input) throws IOException {
                    // javac requires every source unit to belong to a named module location.
                    // Explicit in-memory inputs play the source path role without a filesystem lookup.
                    if (namedModule && input instanceof Source) return location == StandardLocation.SOURCE_PATH;
                    return super.contains(location, input);
                }
            };
            List<String> options = List.of("-proc:none", "-implicit:none", "-Xlint:none", "-encoding", "UTF-8", "-sourcepath", args[2], "-processorpath", args[2], "-classpath", classpath, "--release", args[3]);
            StringWriter compilerOutput = new StringWriter();
            JavacTask task = (JavacTask) compiler.getTask(compilerOutput, files, diagnostics, options, null, sources);
            List<CompilationUnitTree> units = new ArrayList<>(); task.parse().forEach(units::add); task.analyze();
            Trees trees = Trees.instance(task); Elements elements = task.getElements(); Types types=task.getTypes(); SourcePositions positions = trees.getSourcePositions();
            if (args.length > 4) {
                System.setOut(new PrintStream(System.out,false,StandardCharsets.UTF_8));
                var problems = errors(diagnostics);
                Map<String,Object> report = object("format","RocketbrainSignatureCompiler-v20","processorsEnabled",false,
                    "classGenerationEnabled",false,"errors",problems);
                if (problems.isEmpty()) {
                    if (args[4].equals("diagram")) report.put("declarations",diagrams(units,trees,types));
                    else if (args[4].equals("hierarchy")) report.put("hierarchy",new HierarchyInspector(task).inspect(units,byUri));
                    else if (args[4].equals("dataflow")) report.put("dataFlow",dataFlow(units,trees,byUri,args[5],Integer.parseInt(args[6])));
                    else if (args[4].equals("conversion")) {
                        var unit = units.stream().filter(item -> item.getSourceFile().toUri().toString().equals(args[5])).findFirst().orElseThrow();
                        report.put("conversions",new ConversionInspector(task,unit,byUri.get(args[5]).text).inspect());
                    }
                    else if (args[4].equals("constant")) {
                        var unit = units.stream().filter(item -> item.getSourceFile().toUri().toString().equals(args[5])).findFirst().orElseThrow();
                        report.put("constant",new ConstantInspector(task,unit).inspect(Integer.parseInt(args[6]),Integer.parseInt(args[7]),args[8]));
                    }
                    else if (args[4].equals("extraction")) {
                        var unit = units.stream().filter(item -> item.getSourceFile().toUri().toString().equals(args[5])).findFirst().orElseThrow();
                        report.put("extraction",new ExtractionInspector(task,unit,byUri.get(args[5]).text).inspect(args[6],Integer.parseInt(args[7]),args[8]));
                    }
                    else if (args[4].equals("methodInline")) {
                        var unit = units.stream().filter(item -> item.getSourceFile().toUri().toString().equals(args[5])).findFirst().orElseThrow();
                        report.put("methodInline",new InlineMethodInspector(task,unit,byUri.get(args[5]).text)
                            .inspect(Integer.parseInt(args[6]),Integer.parseInt(args[7]),Integer.parseInt(args[8])));
                    }
                    else if (args[4].equals("typeStructure")) {
                        var unit = units.stream().filter(item -> item.getSourceFile().toUri().toString().equals(args[5])).findFirst().orElseThrow();
                        report.put("typeStructure",new StructureInspector(task,byUri).inspect(unit,Integer.parseInt(args[6]),args[7]));
                    }
                    else if (args[4].equals("methodExtract")) {
                        var unit = units.stream().filter(item -> item.getSourceFile().toUri().toString().equals(args[5])).findFirst().orElseThrow();
                        report.put("methodExtract",new ExtractMethodInspector(task,unit,byUri.get(args[5]).text)
                            .inspect(Integer.parseInt(args[6]),Integer.parseInt(args[7]),args[8],Integer.parseInt(args[9])));
                    }
                    else if (args[4].equals("typeImport")) {
                        var unit = units.stream().filter(item -> item.getSourceFile().toUri().toString().equals(args[5])).findFirst().orElseThrow();
                        report.put("typeImport",typeImport(unit,trees,Integer.parseInt(args[6]),Integer.parseInt(args[7]),args[8]));
                    }
                    else if (args[4].equals("staticImport")) {
                        var unit = units.stream().filter(item -> item.getSourceFile().toUri().toString().equals(args[5])).findFirst().orElseThrow();
                        report.put("staticImport",StaticImportInspector.inspect(unit,trees,Integer.parseInt(args[6]),Integer.parseInt(args[7]),args[8]));
                    }
                    else if (args[4].equals("structural")) {
                        report.put("structural",new StructuralSearch(task).search(compiler,files,options,units,byUri,args));
                    }
                }
                System.out.print(json(report));
                return;
            }
            List<Method> methods = new ArrayList<>(); List<Map<String, Object>> calls = new ArrayList<>(); List<Map<String, Object>> references = new ArrayList<>();
            for (CompilationUnitTree unit : units) {
                String uri = unit.getSourceFile().toUri().toString(), text = byUri.get(uri).text;
                new TreePathScanner<Void, Void>() {
                    Method current; int ordinal;
                    public Void visitMethod(MethodTree tree, Void p) {
                        Element element = trees.getElement(getCurrentPath()); if (!(element instanceof ExecutableElement executable)) return super.visitMethod(tree,p);
                        long start = positions.getStartPosition(unit, tree), end = positions.getEndPosition(unit, tree); if (start < 0 || end < start) return super.visitMethod(tree,p);
                        TypeElement owner = (TypeElement) executable.getEnclosingElement(); Method method = new Method(); method.element = executable; method.tree = tree; method.unit = unit; method.uri = uri; method.start = start; method.end = end;
                        String name = executable.getKind() == ElementKind.CONSTRUCTOR ? owner.getSimpleName().toString() : executable.getSimpleName().toString();
                        long headerEnd = tree.getBody() == null ? end : positions.getStartPosition(unit, tree.getBody());
                        int open = tree.getParameters().isEmpty() ? text.lastIndexOf('(', (int)headerEnd) : text.lastIndexOf('(', (int)positions.getStartPosition(unit, tree.getParameters().getFirst()));
                        int cursor = open; while (cursor > start && Character.isWhitespace(text.charAt(cursor - 1))) cursor--;
                        int nameAt = cursor - name.length(); method.nameStart = nameAt >= start && text.regionMatches(nameAt, name, 0, name.length()) ? nameAt : -1;
                        for (VariableElement variable : executable.getParameters()) method.parameters.add(object("type", variable.asType().toString(), "erasure", types.erasure(variable.asType()).toString(), "name", variable.getSimpleName().toString(), "used", false, "annotated", !variable.getAnnotationMirrors().isEmpty() || !variable.asType().getAnnotationMirrors().isEmpty()));
                        method.model = object("key", key(executable), "uri", uri, "owner", owner.getQualifiedName().toString(), "ownerKind", owner.getKind().toString(), "name", name, "constructor", executable.getKind() == ElementKind.CONSTRUCTOR, "start", start, "end", end, "nameStart", method.nameStart, "parameters", method.parameters, "returnType", executable.getReturnType().toString(), "throwsTypes", executable.getThrownTypes().stream().map(Object::toString).toList(), "modifiers", executable.getModifiers().stream().map(Object::toString).sorted().toList(), "annotations", executable.getAnnotationMirrors().stream().map(a -> a.getAnnotationType().toString()).toList(), "generic", !owner.getTypeParameters().isEmpty() || !executable.getTypeParameters().isEmpty(), "varargs", executable.isVarArgs());
                        method.model.put("typeParameters",typeParameters(executable.getTypeParameters()));
                        method.model.put("ownerTypeParameters",typeParameters(owner.getTypeParameters()));
                        method.model.put("ownerSupertypes",types.directSupertypes(owner.asType()).stream().map(Object::toString).toList());
                        method.model.put("erasureKey",owner.getQualifiedName()+"#"+executable.getSimpleName()+"("+String.join(",",executable.getParameters().stream().map(v->types.erasure(v.asType()).toString()).toList())+")");
                        methods.add(method); Method previous=current; int previousOrdinal=ordinal; current=method; ordinal=0; Void result=super.visitMethod(tree,p); current=previous; ordinal=previousOrdinal; method.model.put("bodyIdentifiers", method.identifiers); return result;
                    }
                    public Void visitIdentifier(IdentifierTree tree, Void p) {
                        if (current != null && positions.getStartPosition(unit,tree)>=0) {
                            current.identifiers.add(tree.getName().toString()); Element element=trees.getElement(getCurrentPath());
                            for(int i=0;i<current.element.getParameters().size();i++) if(current.element.getParameters().get(i).equals(element)) current.parameters.get(i).put("used",true);
                        }
                        return super.visitIdentifier(tree,p);
                    }
                    void call(Tree tree, List<? extends ExpressionTree> arguments, boolean constructor) {
                        long start=positions.getStartPosition(unit,tree),end=positions.getEndPosition(unit,tree); Element element=trees.getElement(getCurrentPath());
                        if(start<0 || end<start || !(element instanceof ExecutableElement executable)) return;
                        calls.add(object("uri",uri,"start",start,"end",end,"methodKey",key(executable),"enclosingKey",current==null?"<initializer>":key(current.element),"ordinal",ordinal++,"constructor",constructor,"resultType",trees.getTypeMirror(getCurrentPath()).toString(),"safeArguments",arguments.stream().allMatch(v->safeArgument(getCurrentPath(),v,trees))));
                    }
                    public Void visitMethodInvocation(MethodInvocationTree tree, Void p) { call(tree,tree.getArguments(),false); return super.visitMethodInvocation(tree,p); }
                    public Void visitNewClass(NewClassTree tree, Void p) { call(tree,tree.getArguments(),true); return super.visitNewClass(tree,p); }
                    public Void visitMemberReference(MemberReferenceTree tree, Void p) {
                        Element e=trees.getElement(getCurrentPath()); if(e instanceof ExecutableElement method) references.add(object("uri",uri,"methodKey",key(method),"start",positions.getStartPosition(unit,tree))); return super.visitMemberReference(tree,p);
                    }
                }.scan(unit,null);
            }
            List<Map<String,Object>> edges=new ArrayList<>(); Set<String> external=new TreeSet<>();
            for(Method left:methods) {
                if(left.element.getKind()==ElementKind.CONSTRUCTOR)continue; TypeElement owner=(TypeElement)left.element.getEnclosingElement();
                for(Method right:methods) if(left!=right && right.element.getKind()!=ElementKind.CONSTRUCTOR && elements.overrides(left.element,right.element,owner)) edges.add(object("from",key(left.element),"to",key(right.element)));
                for(Element member:elements.getAllMembers(owner)) if(member instanceof ExecutableElement parent && parent.getKind()!=ElementKind.CONSTRUCTOR && !parent.equals(left.element) && elements.overrides(left.element,parent,owner) && trees.getPath(parent)==null) external.add(key(left.element));
                // getAllMembers hides overridden members; inspect every transitive supertype too.
                ArrayDeque<TypeElement> pending=new ArrayDeque<>(); Set<String> visited=new HashSet<>(); pending.add(owner);
                while(!pending.isEmpty()) {TypeElement type=pending.remove();if(!visited.add(type.getQualifiedName().toString()))continue;
                    for(var superType:task.getTypes().directSupertypes(type.asType())) {if(superType.getKind()!=TypeKind.DECLARED)continue; TypeElement parent=(TypeElement)task.getTypes().asElement(superType);pending.add(parent);
                        for(Element member:parent.getEnclosedElements()) if(member instanceof ExecutableElement parentMethod && parentMethod.getKind()!=ElementKind.CONSTRUCTOR && elements.overrides(left.element,parentMethod,owner) && trees.getPath(parentMethod)==null)external.add(key(left.element));
                    }
                }
            }
            List<Map<String,Object>> errors=errors(diagnostics);
            System.out.print(json(object("format","RocketbrainSignatureCompiler-v20","processorsEnabled",false,"classGenerationEnabled",false,"errors",errors,"methods",methods.stream().map(m->m.model).toList(),"calls",calls,"methodReferences",references,"overrideEdges",edges,"externalOverrides",external)));
        }
    }
}

StaticImportInspector.java:
package rocketbrain.signature;

import com.sun.source.tree.CompilationUnitTree;
import com.sun.source.tree.IdentifierTree;
import com.sun.source.tree.ImportTree;
import com.sun.source.util.TreePathScanner;
import com.sun.source.util.Trees;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import javax.lang.model.element.Element;
import javax.lang.model.element.ElementKind;
import javax.lang.model.element.ExecutableElement;
import javax.lang.model.element.Modifier;
import javax.lang.model.element.TypeElement;

/** Reports attributed uses of an explicitly named static method or field. */
final class StaticImportInspector {
    static Map<String, Object> inspect(CompilationUnitTree unit, Trees trees, int from, int to, String qualified) {
        var positions = trees.getSourcePositions();
        var matches = new ArrayList<Map<String, Object>>();
        String name = qualified.substring(qualified.lastIndexOf('.') + 1);
        String[] selected = { null };
        new TreePathScanner<Void, Void>() {
            @Override public Void visitImport(ImportTree tree, Void unused) { return null; }

            @Override public Void visitIdentifier(IdentifierTree tree, Void unused) {
                if (!tree.getName().contentEquals(name)) return super.visitIdentifier(tree, unused);
                Element element = trees.getElement(getCurrentPath());
                if (element != null && element.getModifiers().contains(Modifier.STATIC) &&
                    element.getEnclosingElement() instanceof TypeElement owner &&
                    List.of(ElementKind.FIELD, ElementKind.ENUM_CONSTANT, ElementKind.METHOD).contains(element.getKind())) {
                    long start = positions.getStartPosition(unit, tree), end = positions.getEndPosition(unit, tree);
                    String identity = owner.getQualifiedName() + "." + name;
                    String signature = element instanceof ExecutableElement method ? SignatureInspector.key(method) :
                        owner.getQualifiedName() + "#" + element.getSimpleName() + ":" + element.asType();
                    matches.add(SignatureInspector.object("start", start, "end", end, "member", identity,
                        "signature", signature, "kind", element.getKind() == ElementKind.METHOD ? "method" : "field"));
                    if (start == from && end == to) selected[0] = identity;
                }
                return super.visitIdentifier(tree, unused);
            }
        }.scan(unit, null);
        return SignatureInspector.object("target", selected[0], "bindings", matches);
    }

    private StaticImportInspector() {}
}

